import{_ as r,o as t,c as e,a2 as s}from"./chunks/framework.B2QVIpOM.js";const d=JSON.parse('{"title":"圣士提反书院 · 年份未注明 · 中一 · 面试","description":"","frontmatter":{"schema":"exam-report-v3","generated_from":"assets/exam-feedback","school_slug":"school-16757f58","school_zh":"圣士提反书院","school_en":"—","grade":"s1","year":"unknown","year_label":"年份未注明","type":"interview","title":"圣士提反书院 · 年份未注明 · 中一 · 面试","anonymous":true,"source_ids":["C1821-SSC-U","HOT22-SSC"],"rounds":["unknown","r1"]},"headers":[],"relativePath":"reports/school-16757f58/s1/unknown-interview.md","filePath":"reports/school-16757f58/s1/unknown-interview.md"}'),n={name:"reports/school-16757f58/s1/unknown-interview.md"};function p(a,o,c,l,g,h){return t(),e("div",null,[...o[0]||(o[0]=[s('<h1 id="圣士提反书院-·-年份未注明-·-中一-·-面试" tabindex="-1">圣士提反书院 · 年份未注明 · 中一 · 面试 <a class="header-anchor" href="#圣士提反书院-·-年份未注明-·-中一-·-面试" aria-label="Permalink to &quot;圣士提反书院 · 年份未注明 · 中一 · 面试&quot;">​</a></h1><p><a href="/hk-exam-web/schools/school-16757f58">← 返回圣士提反书院资料库</a></p><blockquote><p>以下内容根据考试及面试资料整理，已作匿名化与书面化处理，非逐字实录。具体安排请以当次考试通知为准。</p></blockquote><h2 id="record-c1821-ssc-u" tabindex="-1">资料来源：【其它机构】升中面试经验汇总_18-21.pdf <a class="header-anchor" href="#record-c1821-ssc-u" aria-label="Permalink to &quot;资料来源：【其它机构】升中面试经验汇总_18-21.pdf {#record-c1821-ssc-u}&quot;">​</a></h2><p><strong>资料类型：</strong> 不同学生的历史面试反馈汇编</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="轮次未注明-·-请以当次考试通知为准" tabindex="-1">轮次未注明 · 请以当次考试通知为准 <a class="header-anchor" href="#轮次未注明-·-请以当次考试通知为准" aria-label="Permalink to &quot;轮次未注明 · 请以当次考试通知为准&quot;">​</a></h3><blockquote><p><strong>英语：</strong> 英语</p><p><strong>朗读与阅读理解</strong></p><p>有1分钟准备后朗读文章的反馈，另有指定生词朗读及理解问答。</p><p><strong>学业、职务与才能</strong></p><p>自我介绍后谈校内或班内名次、担任的职务、小学六年最珍视的奖项、独诵比赛成绩；说明能为学校带来什么才能，以及如何用才能帮助别人。</p><p><strong>择校与在校计划</strong></p><p>申请了哪些学校、若全获录取如何选择；最想在校学习什么、参加什么学会，有什么想问学校；怎样到校、由谁陪同、兄弟姊妹是否在校就读。</p><p><strong>家庭与生活</strong></p><p>父母职业及是否为旧生、是否希望孩子入读；闲暇活动、家庭共同活动、与朋友争执的例子，以及日常怎样助人。老师也会询问普通话能力，并请考生用普通话介绍家人。</p></blockquote><blockquote><p><strong>语文：</strong> 中文，部分普通话</p><p><strong>阅读、书籍与兴趣</strong></p><p>朗读文章并答题，介绍一本中文书、一本英文书及喜欢的作者；谈最喜欢的季节、兴趣、常做的运动、某项技能已达等级及总级数、成绩与未来职业。</p><p><strong>学校适配与交通</strong></p><p>评价校园环境、说明择校原因、优缺点及为何应获录取；若多校录取怎样选择、怎样为学校争光。住处较远时如何解决交通、是否考虑寄宿；父母为旧生时是否曾带自己到校。</p><p><strong>家庭与领导情境</strong></p><p>评价父亲及是否希望像父亲一样；当班会会长会举办什么活动、怎样安排、担任什么角色，若有同学不喜欢自己如何处理。普通话介绍家人，并回答在街上遇见特首会问什么。</p></blockquote><blockquote><p><strong>数学：</strong> 语言未注明</p><p><strong>数学问答</strong></p><p>有数学提问，具体题目未明确。</p></blockquote><h2 id="record-hot22-ssc" tabindex="-1">资料来源：热门港校面试真题集：中学篇.pdf <a class="header-anchor" href="#record-hot22-ssc" aria-label="Permalink to &quot;资料来源：热门港校面试真题集：中学篇.pdf {#record-hot22-ssc}&quot;">​</a></h2><p><strong>资料类型：</strong> 2022/23机构汇编中的历史面试题</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="第一轮-·-原文明示" tabindex="-1">第一轮 · 原文明示 <a class="header-anchor" href="#第一轮-·-原文明示" aria-label="Permalink to &quot;第一轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>语文：</strong> 中文（口语未注明）</p><p><strong>人物阅读</strong></p><p>阅读贝多芬生平并回答问题；自我介绍。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>科技阅读</strong></p><p>阅读无人驾驶巴士主题文章并回答问题。</p><p><strong>个人与情境问答</strong></p><p>自我介绍；面试后会做什么；好友做了自己不喜欢的事会如何处理；有什么才能；在校喜欢做什么、最喜欢哪科。</p></blockquote>',18)])])}const u=r(n,[["render",p]]);export{d as __pageData,u as default};
